SELECT * FROM monitor_sys_gen_server_component
WHERE monitor_sys_gen_server_id = #{serverId}
ORDER BY monitor_sys_gen_server_component_sort_order ASC, monitor_sys_gen_server_component_create_time ASC

SELECT * FROM monitor_sys_gen_server_component
WHERE monitor_sys_gen_server_id = #{serverId} 
AND monitor_sys_gen_server_component_type = #{componentType}
ORDER BY monitor_sys_gen_server_component_sort_order ASC

SELECT * FROM monitor_sys_gen_server_component
WHERE monitor_sys_gen_server_id = #{serverId} 
AND monitor_sys_gen_server_component_expression_type = #{expressionType}
ORDER BY monitor_sys_gen_server_component_sort_order ASC

