UPDATE monitor_sys_gen_server_component SET monitor_sys_gen_server_component_position = CASE monitor_sys_gen_server_component_id
WHEN #{component.monitorSysGenServerComponentId} THEN #{component.monitorSysGenServerComponentPosition}
ELSE monitor_sys_gen_server_component_position END, monitor_sys_gen_server_component_update_time = CASE monitor_sys_gen_server_component_id
WHEN #{component.monitorSysGenServerComponentId} THEN #{component.monitorSysGenServerComponentUpdateTime}
ELSE monitor_sys_gen_server_component_update_time END WHERE monitor_sys_gen_server_component_id IN
#{component.monitorSysGenServerComponentId}
